def apply(inputs, premises):
    names = inputs["asset_descriptions"]
    categories = inputs["asset_categories"]
    values = inputs["asset_values"]
    debtor_count = int(inputs["debtor_count"])
    citations = premises["rule_citations"]
    rule_categories = premises["rule_categories"]
    caps = premises["rule_caps"]
    unlimited = premises["rule_unlimited"]
    per_debtor = premises["rule_caps_apply_per_debtor"]
    claims = {}
    for i in range(len(names)):
        asset_claims = []
        for j in range(len(citations)):
            if rule_categories[j] == categories[i] or rule_categories[j] == "any":
                claim_value = float(values[i])
                if not bool(unlimited[j]):
                    cap = float(caps[j])
                    if bool(per_debtor[j]):
                        cap = cap * debtor_count
                    claim_value = min(float(values[i]), cap)
                asset_claims = asset_claims + [{"citation": citations[j], "claim_value": claim_value}]
        claims[names[i]] = asset_claims
    return {"asset_descriptions": names, "claims": claims}

